const [sr, ls] = await Promise.all([
  tools.web_search({ queries: [
    "find-skills skill 描述 skills.sh 安装量最高",
    "skill 是什么 claude code agent skills 概念 介绍",
    "\"skills.sh\" top skills 排行 安装次数",
  ]}),
  tools.pwsh({ command: "Get-ChildItem -Path $env:USERPROFILE -Directory -Filter '.claude' -Force -ErrorAction SilentlyContinue | Select-Object -ExpandProperty FullName; Get-ChildItem -Path \"$env:USERPROFILE\\.claude\\skills\" -Directory -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Name", description: "List user skills directories" }),
]);
console.log(sr.content ?? "(no summary)");
for (const s of sr.sources.slice(0, 10)) console.log(`\n--- ${s.title ?? ""}\n${s.url}\n${s.snippet ?? ""}`);
console.log("\n=== local ===");
if (ls.kind === "foreground") console.log(ls.stdout.text, ls.stderr.text);
